def solution(grid):
    # Relax every cell from its neighbours, sweep after sweep, until nothing changes.
    # Correct (Bellman-Ford on a grid) but up to O(cells) sweeps of O(cells) work each.
    n = len(grid)
    if n == 0 or grid[0][0] != '0' or grid[n - 1][n - 1] != '0':
        return -1
    big = n * n + 1
    dist = [[big] * n for _ in range(n)]
    dist[0][0] = 1
    changed = True
    while changed:
        changed = False
        for r in range(n):
            for c in range(n):
                if grid[r][c] != '0' or dist[r][c] == big:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == '0' and dist[r][c] + 1 < dist[nr][nc]:
                            dist[nr][nc] = dist[r][c] + 1
                            changed = True
    return dist[n - 1][n - 1] if dist[n - 1][n - 1] < big else -1
